SELECT FP.FINPROD_ID finprodId, FP.FINPROD_ABBR finprodName, TBBS.HAPPEN_DATE happenDate, TBBS.TAX_P_TYPE taxPType, TBBS.VAT_TYPE vatType, (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 FROM TAX_BOK_BALANCE_SUM TBBS INNER JOIN BOK_BOOKSET B ON B.BOOKSET_ID = TBBS.BOOKSET_ID INNER JOIN FIN_PRODUCT FP ON B.ACCT_SUBJECT_ID=FP.FINPROD_ID WHERE 1=1
AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
null) or TBBS.BOOKSET_ID in (
#{finprodId}
AND (TBBS.TAX_P_TYPE in
null) or TBBS.TAX_P_TYPE in (
#{pType}
)
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
GROUP BY FP.FINPROD_ID, FP.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE
HAVING SUM(TAX_AMT) != 0
union SELECT FP2.FINPROD_ID finprodId, FP2.FINPROD_ABBR finprodName, TBBS.HAPPEN_DATE happenDate, TBBS.TAX_P_TYPE taxPType, TBBS.VAT_TYPE vatType, (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 FROM TAX_BOK_BALANCE_SUM TBBS INNER JOIN BOK_BOOKSET B ON B.BOOKSET_ID = TBBS.BOOKSET_ID INNER JOIN FIN_PRODUCT_ADD FPA ON B.ACCT_SUBJECT_ID=FPA.PORTFOLIO_ID INNER JOIN FIN_PRODUCT FP2 ON FPA.FINPROD_ID=FP2.FINPROD_ID AND FP2.P_FINPROD_ID IS NULL WHERE 1=1
AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
#{finprodId}
AND TBBS.TAX_P_TYPE in
#{pType}
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
GROUP BY FP2.FINPROD_ID, FP2.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE
HAVING SUM(TAX_AMT) != 0

SELECT FP.FINPROD_ID finprodId, FP.FINPROD_ABBR finprodName, BDI.BUSI_ID assetId, FP2.FINPROD_ABBR assetIdName, TBBS.HAPPEN_DATE happenDate, TBBS.TAX_P_TYPE taxPType, TBBS.VAT_TYPE vatType, (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 FROM TAX_BOK_BALANCE TBBS INNER JOIN BOK_BOOKSET B ON B.BOOKSET_ID = TBBS.BOOKSET_ID INNER JOIN FIN_PRODUCT FP ON B.ACCT_SUBJECT_ID=FP.FINPROD_ID INNER JOIN BOK_DETAIL_ID BDI ON TBBS.BOK_DETAIL_ID = BDI.BOK_DETAIL_ID and B.BOOKSET_ID=BDI.BOOKSET_ID LEFT JOIN FIN_PRODUCT FP2 ON BDI.BUSI_ID = FP2.FINPROD_ID WHERE 1=1 AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
#{finprodId}
AND TBBS.TAX_P_TYPE in
#{pType}
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
AND BDI.BUSI_ID in
#{assetId}
GROUP BY FP.FINPROD_ID, FP.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE, BDI.BUSI_ID, FP2.FINPROD_ABBR
HAVING SUM(TAX_AMT) != 0
UNION SELECT FP.FINPROD_ID finprodId, FP.FINPROD_ABBR finprodName, BDI.BUSI_ID assetId, IFNULL(FP2.FINPROD_ABBR,BDI.BUSI_ID) assetIdName, TBBS.HAPPEN_DATE happenDate, TBBS.TAX_P_TYPE taxPType, TBBS.VAT_TYPE vatType, (case when TBBS.TAX_P_TYPE='01' then SUM(TAX_AMT) else null end) AS taxAmt, (case when TBBS.TAX_P_TYPE='02' then SUM(TAX_AMT) else null end) AS taxAmt2 FROM TAX_BOK_BALANCE TBBS INNER JOIN BOK_BOOKSET B ON B.BOOKSET_ID = TBBS.BOOKSET_ID INNER JOIN FIN_PRODUCT_ADD FPA ON B.ACCT_SUBJECT_ID=FPA.PORTFOLIO_ID INNER JOIN FIN_PRODUCT FP ON FPA.FINPROD_ID=FP.FINPROD_ID AND FP.P_FINPROD_ID IS NULL INNER JOIN BOK_DETAIL_ID BDI ON TBBS.BOK_DETAIL_ID = BDI.BOK_DETAIL_ID and B.BOOKSET_ID=BDI.BOOKSET_ID LEFT JOIN FIN_PRODUCT FP2 ON BDI.BUSI_ID = FP2.FINPROD_ID WHERE 1=1 AND TBBS.VAT_TYPE in
#{type}
AND TBBS.BOOKSET_ID in
#{finprodId}
AND TBBS.TAX_P_TYPE in
#{pType}
AND TBBS.VAT_TYPE in
#{vatType}
AND TBBS.HAPPEN_DATE <= STR_TO_DATE(#{endDate },'%Y-%m-%d') AND TBBS.HAPPEN_DATE >= STR_TO_DATE(#{startDate },'%Y-%m-%d')
AND BDI.BUSI_ID in
#{assetId}
GROUP BY FP.FINPROD_ID, FP.FINPROD_ABBR, TBBS.HAPPEN_DATE, TBBS.TAX_P_TYPE, TBBS.VAT_TYPE, BDI.BUSI_ID, FP2.FINPROD_ABBR
HAVING SUM(TAX_AMT) != 0
